package com.aabhix.camera;

import android.app.Activity;
import android.graphics.Color;
import android.hardware.camera2.*;
import android.util.Range;
import android.view.*;
import android.widget.*;
import com.aabhix.camera.domain.*;
import java.util.*;
import java.util.function.Consumer;

/** Compact live sensor controls, keeping most of the viewfinder visible. */
public final class ProControlPanel extends LinearLayout {
    private final Activity activity;private final CameraController camera;private final Consumer<String> status;
    private Consumer<Boolean> visibilityListener;
    public void selectControl(String key){if(!chips.containsKey(key))throw new IllegalArgumentException("Unknown Pro control");selected=key;bind();}
    public void onVisibility(Consumer<Boolean> listener){visibilityListener=listener;listener.accept(getVisibility()==VISIBLE);}
    @Override public void setVisibility(int visibility){super.setVisibility(visibility);if(visibilityListener!=null)visibilityListener.accept(visibility==VISIBLE);}
    private final LinkedHashMap<String,Button> chips=new LinkedHashMap<>();private String selected="EV";
    private final LinearLayout adjustment;private final SeekBar slider;private final Button auto,ae,awb;private final TextView value,rangeHint;private boolean binding;
    public ProControlPanel(Activity activity,CameraController camera,Runnable lens,Consumer<String> status){super(activity);this.activity=activity;this.camera=camera;this.status=status;setOrientation(VERTICAL);setBackgroundColor(0xe6101010);setPadding(dp(4),dp(2),dp(4),dp(2));
        HorizontalScrollView scroll=new HorizontalScrollView(activity);scroll.setHorizontalScrollBarEnabled(false);LinearLayout fields=row();for(String key:new String[]{"EV","ISO","S","WB","Focus"}){Button chip=button(key);chip.setContentDescription(key+" control");chip.setOnClickListener(v->{if(key.equals("EV")&&camera.manualIso()>0){camera.proControls(false,200,8000000,camera.whiteBalance());camera.advancedControls(false,camera.whiteBalanceLocked(),recordLock(),camera.antiBanding());status.accept("EV adjusts automatic exposure · ISO and shutter restored to Auto");}selected=key;bind();});chips.put(key,chip);fields.addView(chip,new LinearLayout.LayoutParams(dp(70),dp(48)));}Button lenses=button("Lens");lenses.setOnClickListener(v->lens.run());fields.addView(lenses,new LinearLayout.LayoutParams(dp(64),dp(48)));scroll.addView(fields);addView(scroll,new LayoutParams(-1,dp(48)));
        adjustment=row();auto=button("Auto");auto.setContentDescription("Restore automatic selected Pro control");auto.setOnClickListener(v->automatic());adjustment.addView(auto,new LayoutParams(dp(54),dp(44)));slider=new SeekBar(activity);slider.setMax(1000);adjustment.addView(slider,new LayoutParams(0,dp(44),1));value=new TextView(activity);value.setTextColor(Color.WHITE);value.setTextSize(12);value.setGravity(Gravity.CENTER);adjustment.addView(value,new LayoutParams(dp(78),dp(44)));addView(adjustment);
        rangeHint=new TextView(activity);rangeHint.setTextColor(0xffbbbbbb);rangeHint.setTextSize(10);rangeHint.setGravity(Gravity.CENTER);addView(rangeHint,new LayoutParams(-1,dp(20)));
        slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){if(user&&!binding)apply(p);}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});
        LinearLayout actions=row();ae=button("AE lock");ae.setOnClickListener(v->{camera.advancedControls(!camera.exposureLocked(),camera.whiteBalanceLocked(),recordLock(),camera.antiBanding());});awb=button("WB lock");awb.setOnClickListener(v->{camera.advancedControls(camera.exposureLocked(),!camera.whiteBalanceLocked(),recordLock(),camera.antiBanding());});Button reset=button("Auto reset");reset.setOnClickListener(v->{camera.controls(0,1,-1);camera.proControls(false,200,8000000,1);camera.advancedControls(false,false,recordLock(),camera.antiBanding());status.accept("Automatic exposure, focus and white balance restored");});Button close=button("×");close.setContentDescription("Close inline Pro controls");close.setOnClickListener(v->setVisibility(GONE));for(Button b:new Button[]{ae,awb,reset,close})actions.addView(b,new LayoutParams(0,dp(44),1));addView(actions);bind();
    }
    private boolean recordLock(){return activity.getSharedPreferences("settings",0).getBoolean("recordWbLock",false)&&camera.hasWhiteBalanceLock();}
    private void bind(){binding=true;while(adjustment.getChildCount()>3)adjustment.removeViewAt(3);auto.setVisibility(VISIBLE);slider.setVisibility(VISIBLE);value.setVisibility(VISIBLE);slider.setMax(selected.equals("EV")?Math.max(0,camera.evMax()-camera.evMin()):1000);slider.setEnabled(true);auto.setEnabled(true);slider.setContentDescription(selected+" live slider");
        if(selected.equals("ISO")){Range<Integer> range=camera.isoRange();boolean enabled=camera.hasManualSensor()&&range!=null;slider.setEnabled(enabled);auto.setEnabled(enabled);if(enabled)slider.setProgress(ProValues.progress(sensorIso(),range.getLower(),range.getUpper()));}
        else if(selected.equals("S")){Range<Long> range=camera.usableExposureRange();boolean enabled=camera.hasManualSensor()&&range!=null;slider.setEnabled(enabled);auto.setEnabled(enabled);if(enabled)slider.setProgress(ProValues.progress(sensorTime(),range.getLower(),range.getUpper()));}
        else if(selected.equals("EV")){slider.setEnabled(camera.manualIso()==0&&camera.evMax()>camera.evMin());slider.setProgress(camera.currentEv()-camera.evMin());auto.setEnabled(true);}
        else if(selected.equals("Focus")){slider.setEnabled(camera.hasManualFocus());auto.setEnabled(camera.hasManualFocus());slider.setProgress(Math.round(Math.max(0,camera.currentFocus())*1000));}
        else{slider.setVisibility(GONE);value.setVisibility(GONE);HorizontalScrollView list=new HorizontalScrollView(activity);LinearLayout presets=row();for(int mode:camera.whiteBalanceModes())if(mode>0&&mode<WB.length){Button b=button(WB[mode]);b.setContentDescription("White balance "+WB[mode]);b.setOnClickListener(v->{camera.proControls(camera.manualIso()>0,sensorIso(),sensorTime(),mode);camera.advancedControls(camera.exposureLocked(),false,recordLock(),camera.antiBanding());});presets.addView(b,new LayoutParams(-2,dp(44)));}list.addView(presets);adjustment.addView(list,new LayoutParams(0,dp(44),1));}
        rangeHint.setText(selected.equals("ISO")?"Sensor ISO range "+camera.isoRange():selected.equals("S")?"Shutter "+(camera.usableExposureRange()==null?"unavailable":MonitorMath.shutter(camera.usableExposureRange().getLower())+" – "+MonitorMath.shutter(camera.usableExposureRange().getUpper())):selected.equals("EV")?"EV "+String.format(Locale.ROOT,"%+.1f to %+.1f",camera.evMin()*camera.evStep(),camera.evMax()*camera.evStep())+" · automatic exposure":selected.equals("Focus")?"AF / manual focus · active lens capability":"White balance presets · active lens capability");binding=false;refresh();
    }
    private int sensorIso(){TotalCaptureResult result=camera.latestResult();Integer measured=result==null?null:result.get(CaptureResult.SENSOR_SENSITIVITY);Range<Integer> range=camera.isoRange();return range==null?200:range.clamp(camera.manualIso()>0?camera.manualIso():measured==null?range.getLower():measured);}
    private long sensorTime(){TotalCaptureResult result=camera.latestResult();Long measured=result==null?null:result.get(CaptureResult.SENSOR_EXPOSURE_TIME);Range<Long> range=camera.usableExposureRange();return range==null?8000000:range.clamp(camera.manualIso()>0?camera.manualExposure():measured==null?8000000:measured);}
    private void apply(int progress){try{if(selected.equals("ISO")){Range<Integer> range=camera.isoRange();if(range==null)return;camera.proControls(true,(int)ProValues.logarithmic(progress,range.getLower(),range.getUpper()),sensorTime(),camera.whiteBalance());camera.advancedControls(false,camera.whiteBalanceLocked(),recordLock(),camera.antiBanding());}else if(selected.equals("S")){Range<Long> range=camera.usableExposureRange();if(range==null)return;camera.proControls(true,sensorIso(),ProValues.logarithmic(progress,range.getLower(),range.getUpper()),camera.whiteBalance());camera.advancedControls(false,camera.whiteBalanceLocked(),recordLock(),camera.antiBanding());}else if(selected.equals("Focus"))camera.controls(camera.currentEv(),camera.currentZoom(),progress/1000f);else if(selected.equals("EV"))camera.controls(camera.evMin()+progress,camera.currentZoom(),camera.currentFocus());}catch(IllegalArgumentException e){status.accept(e.getMessage());}}
    private void automatic(){if(selected.equals("WB")){camera.proControls(camera.manualIso()>0,sensorIso(),sensorTime(),CaptureRequest.CONTROL_AWB_MODE_AUTO);camera.advancedControls(camera.exposureLocked(),false,recordLock(),camera.antiBanding());}else if(selected.equals("Focus"))camera.controls(camera.currentEv(),camera.currentZoom(),-1);else{camera.proControls(false,200,8000000,camera.whiteBalance());camera.advancedControls(false,camera.whiteBalanceLocked(),recordLock(),camera.antiBanding());status.accept("Auto exposure · ISO and shutter");}bind();}
    private static final String[] WB={"Off","Auto","Tungsten","Fluorescent","Warm fluorescent","Daylight","Cloudy","Twilight","Shade"};
    public void cameraChanged(){bind();}
    private String evText(){return camera.evStep()>0?String.format(Locale.ROOT,"%+.1f",camera.currentEv()*camera.evStep()):camera.currentEv()+" steps";}
    public void refresh(){if(getVisibility()!=VISIBLE)return;if(selected.equals("EV"))slider.setEnabled(camera.manualIso()==0&&camera.evMax()>camera.evMin());TotalCaptureResult result=camera.latestResult();Integer iso=result==null?null:result.get(CaptureResult.SENSOR_SENSITIVITY);Long exposure=result==null?null:result.get(CaptureResult.SENSOR_EXPOSURE_TIME);String isoText=(camera.manualIso()==0?"A ":"")+(iso==null?"—":iso);String timeText=(camera.manualIso()==0?"A ":"")+MonitorMath.shutter(exposure);String wb=camera.whiteBalance()>=0&&camera.whiteBalance()<WB.length?WB[camera.whiteBalance()]:"—";chips.get("ISO").setText("ISO\n"+isoText);chips.get("S").setText("S\n"+timeText);chips.get("EV").setText("EV\n"+evText());chips.get("WB").setText("WB\n"+wb);chips.get("Focus").setText(camera.hasManualFocus()?(camera.currentFocus()<0?"Focus\nAF":"Focus\nMF"):"Focus\nFixed");for(Map.Entry<String,Button> chip:chips.entrySet())chip.getValue().setTextColor(chip.getKey().equals(selected)?0xffffd54a:Color.WHITE);value.setText(selected.equals("ISO")?isoText:selected.equals("S")?timeText:selected.equals("EV")?(camera.manualIso()>0?"Auto AE only":evText()):camera.currentFocus()<0?"AF":String.format(Locale.ROOT,"MF %.2f",camera.currentFocus()));ae.setEnabled(camera.hasExposureLock()&&camera.manualIso()==0);awb.setEnabled(camera.hasWhiteBalanceLock());ae.setTextColor(camera.exposureLocked()?0xffffd54a:Color.WHITE);awb.setTextColor(camera.whiteBalanceLocked()?0xffffd54a:Color.WHITE);}
    private LinearLayout row(){LinearLayout row=new LinearLayout(activity);row.setGravity(Gravity.CENTER_VERTICAL);return row;}
    private Button button(String text){Button b=new Button(activity);b.setText(text);b.setAllCaps(false);b.setTextSize(11);b.setTextColor(Color.WHITE);b.setBackgroundColor(Color.TRANSPARENT);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(6),0,dp(6),0);return b;}
    private int dp(float value){return Math.round(value*getResources().getDisplayMetrics().density);}
}
